class TacticalButton(tk.Button):
    def __init__(self, master, variant="normal", **kw):
        bg_col = BTN_BG
        fg_col = TEXT_PRIMARY
        if variant == "primary":
            bg_col = "#238636"
            fg_col = "#ffffff"
        elif variant == "danger":
            bg_col = "#da3633"
            fg_col = "#ffffff"
        elif variant == "accent":
            bg_col = "#1f6feb"
            fg_col = "#ffffff"

        kw.setdefault('bg', bg_col)
        kw.setdefault('fg', fg_col)
        kw.setdefault('relief', tk.FLAT)
        kw.setdefault('activebackground', ACCENT_BLUE)
        kw.setdefault('activeforeground', "#ffffff")
        kw.setdefault('font', ("Segoe UI", 10, "bold"))
        kw.setdefault('cursor', "hand2")
        kw.setdefault('padx', 12)
        kw.setdefault('pady', 6)
        super().__init__(master, **kw)

        self.default_bg = kw['bg']
        self.default_fg = kw['fg']
        self.variant = variant

        self.bind("<Enter>", self.on_enter)
        self.bind("<Leave>", self.on_leave)

    def on_enter(self, e):
        if self.variant == "normal":
            self.config(bg=BTN_HOVER)
        elif self.variant == "primary":
            self.config(bg="#2ea043")
        elif self.variant == "danger":
            self.config(bg="#f85149")
        elif self.variant == "accent":
            self.config(bg="#388bfd")

    def on_leave(self, e):
        self.config(bg=self.default_bg, fg=self.default_fg)


